const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; addSql: string; delSql: string | null }> = {
  __host_response_sg: { kind: "set", addSql: `INSERT INTO "__host_response_sg" ("witness_digest", "ordinal", "file_digest", "query_digest", "caller", "callee", "start_byte", "end_byte") VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT ("witness_digest", "ordinal") DO UPDATE SET "file_digest" = excluded."file_digest", "query_digest" = excluded."query_digest", "caller" = excluded."caller", "callee" = excluded."callee", "start_byte" = excluded."start_byte", "end_byte" = excluded."end_byte"`, delSql: `DELETE FROM "__host_response_sg" WHERE "witness_digest" = ? AND "ordinal" = ? AND "file_digest" = ? AND "query_digest" = ? AND "caller" = ? AND "callee" = ? AND "start_byte" = ? AND "end_byte" = ?` },
  file: { kind: "set", addSql: `INSERT OR IGNORE INTO "file" ("file", "file_digest") VALUES (?, ?)`, delSql: `DELETE FROM "file" WHERE "file" = ? AND "file_digest" = ?` },
  query_value: { kind: "set", addSql: `INSERT OR IGNORE INTO "query_value" ("query_digest") VALUES (?)`, delSql: `DELETE FROM "query_value" WHERE "query_digest" = ?` },
};

function arrivalStatement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`extraction_fork_callgraph: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`extraction_fork_callgraph: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.delSql === null) {
      throw new Error(`extraction_fork_callgraph: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.delSql, args: bindArgs(arrival.row) };
  }
  return { sql: template.addSql, args: bindArgs(arrival.row) };
}

function applyArrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrivalStatement);
  return seam.runner.batch(seam.db, statements);
}

